CREATE OR ALTER PROCEDURE [dbo].[uspPackingOrder_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ProductionBatchId UNIQUEIDENTIFIER = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @PackingOrderNumber NVARCHAR(MAX) = NULL
	, @PackingDate DATETIME2 = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ProductionBatchId]
			, j1.[BatchNo] AS [ProductionBatchName]
			, t.[OrderId]
			, j2.[OrderNo] AS [OrderName]
			, t.[PlannedQty]
			, t.[Status]
			, t.[PackingOrderNumber]
			, t.[PackingDate]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[PackingOrder] AS t
		LEFT JOIN [dbo].[ProductionBatche] AS j1 ON j1.[Id] = t.[ProductionBatchId]
		LEFT JOIN [dbo].[Order] AS j2 ON j2.[Id] = t.[OrderId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[PackingOrderNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ProductionBatchId IS NULL OR t.[ProductionBatchId] = @ProductionBatchId)
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@PackingOrderNumber, '') = '' OR t.[PackingOrderNumber] LIKE CONCAT('%', @PackingOrderNumber, '%'))
			AND (@PackingDate IS NULL OR t.[PackingDate] = @PackingDate)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchName' THEN r.[ProductionBatchName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchName' THEN r.[ProductionBatchName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderName' THEN r.[OrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderName' THEN r.[OrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedQty' THEN r.[PlannedQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedQty' THEN r.[PlannedQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packingOrderNumber' THEN r.[PackingOrderNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packingOrderNumber' THEN r.[PackingOrderNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packingDate' THEN r.[PackingDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packingDate' THEN r.[PackingDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
